css:
:root{--navy:#0E2A43;--navy2:#0A2033;--orange:#F26A21;--orange2:#ff8336;--ink:#122a3f;--body:#4b5b69;--mut:#8295a4;--line:#e6edf3;--bg:#eef3f9;--bg2:#e7eef7;--card:#fff;--ok:#1f7a4d;--head:'Inter',system-ui,sans-serif;--sans:'Inter',system-ui,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--body);font-family:var(--sans);font-size:16px;line-height:1.6;overflow-x:hidden}
img.logo{width:auto;max-width:200px}
input,select,textarea{min-width:0}
.ct-grid,.two,.price-grid,.area-grid,.finder{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
.book-grid{grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr)}
.book-card,.book-l,.price-l,.area-l,.ct-card>div{min-width:0}
.ct-card p,.ct-card a,.f-cont a,.lead{overflow-wrap:anywhere}
.wrap{max-width:1220px;margin:0 auto;padding:0 22px}
a{text-decoration:none;color:inherit}
h1,h2,h3,h4{font-family:var(--head);color:var(--navy);margin:0;line-height:1.06;font-weight:800;letter-spacing:-.02em}
.u{display:block;width:100%;height:100%;object-fit:cover}
.btn{display:inline-flex;align-items:center;gap:9px;font-family:var(--head);font-weight:600;font-size:1rem;padding:15px 26px;border-radius:999px;cursor:pointer;border:2px solid transparent;transition:.15s}
.btn svg{width:17px;height:17px}
.btn-o{background:var(--orange);color:#fff}.btn-o:hover{background:var(--orange2)}
.btn-navy{background:var(--navy);color:#fff}.btn-navy:hover{background:var(--navy2)}
.btn-out{background:transparent;border-color:#cfd9e2;color:var(--navy)}.btn-out:hover{border-color:var(--navy)}
.btn-ghostline{background:transparent;border-color:rgba(255,255,255,.4);color:#fff}.btn-ghostline:hover{border-color:#fff}
.btn-wt{background:#fff;color:var(--navy)}
.eyebrow{display:inline-flex;align-items:center;gap:9px;background:#fff;border:1px solid var(--line);color:var(--navy);font-family:var(--head);font-weight:600;font-size:.82rem;padding:7px 15px;border-radius:999px;box-shadow:0 6px 18px -12px rgba(14,42,67,.4)}
.eyebrow::before{content:"";width:9px;height:9px;border-radius:50%;background:var(--orange)}
.sec-head{text-align:center;max-width:720px;margin:0 auto 38px}
.sec-head h2{font-size:clamp(2rem,4vw,3rem);margin:14px 0 10px}
.sec-head p{font-size:1.06rem}
.k{font-family:var(--head);color:var(--orange);font-weight:600;letter-spacing:1px;font-size:.84rem;text-transform:uppercase}
section{padding:72px 0}
.util{background:var(--navy2);color:#b9c8d6;font-size:.8rem}
.util .wrap{display:flex;justify-content:space-between;gap:14px;padding:8px clamp(18px,2.6vw,46px);max-width:none;text-transform:uppercase;letter-spacing:.5px;font-weight:600}
.util a{color:var(--orange2)}
header.site{position:sticky;top:0;z-index:60;background:#fff;border-bottom:1px solid var(--line)}
.hd{display:flex;align-items:center;gap:22px;padding:13px clamp(18px,2.6vw,46px);max-width:none}
.hd .logo{height:46px}
nav.main{margin-left:auto;display:flex;gap:2px}
nav.main>ul{display:flex;list-style:none;margin:0;padding:0;gap:2px}
nav.main>ul>li{position:relative}
nav.main>ul>li>a{display:block;font-family:var(--head);font-weight:500;font-size:.96rem;color:var(--navy);padding:10px 14px;border-radius:9px;white-space:nowrap}
nav.main>ul>li>a:hover,nav.main a.active{color:var(--orange)}
.submenu{position:absolute;top:100%;left:0;min-width:250px;background:#fff;border:1px solid var(--line);border-radius:13px;box-shadow:0 22px 46px -18px rgba(14,42,67,.3);padding:8px;opacity:0;visibility:hidden;transform:translateY(7px);transition:.15s;display:flex;flex-direction:column;z-index:80}
li.has:hover .submenu{opacity:1;visibility:visible;transform:none}
.submenu a{padding:9px 12px;border-radius:8px;font-size:.92rem;color:var(--navy)}.submenu a:hover{background:var(--bg);color:var(--orange)}
.hd .hcall{display:flex;align-items:center;gap:10px;margin-left:auto}
.hd .hcall .hc-ic{width:44px;height:44px;border-radius:50%;background:var(--orange);color:#fff;display:grid;place-items:center}.hd .hcall svg{width:20px;height:20px}
.hd .hcall small{display:block;color:var(--mut);font-size:.72rem;font-weight:600;white-space:nowrap}.hd .hcall b{font-family:var(--head);font-size:1.2rem;color:var(--navy);white-space:nowrap}
.hd .hbook{margin-left:8px}
.hero{background:var(--bg);background-image:radial-gradient(rgba(14,42,67,.05) 1.3px,transparent 1.3px);background-size:24px 24px}
.hero .wrap{display:grid;grid-template-columns:1.02fr .98fr;gap:40px;align-items:center;padding:64px 22px 72px}
.hero h1{font-size:clamp(2.6rem,5.4vw,4.4rem);margin:20px 0 18px}
.hero h1 .o{color:var(--orange)}
.hero .sub{font-size:1.14rem;max-width:44ch;margin:0 0 26px}
.hero .acts{display:flex;gap:14px;flex-wrap:wrap;align-items:center}
.hero .play{display:inline-flex;align-items:center;gap:11px;font-family:var(--head);font-weight:600;color:var(--navy)}
.hero .play span{width:46px;height:46px;border-radius:50%;border:2px solid var(--navy);display:grid;place-items:center}.hero .play svg{width:16px;height:16px;margin-left:2px}
.hero .trust{display:flex;gap:26px;flex-wrap:wrap;margin-top:34px;padding-top:26px;border-top:1px solid var(--line)}
.hero .trust div{display:flex;gap:12px;align-items:flex-start}
.hero .trust .ti{flex:none;width:40px;height:40px;border-radius:11px;background:#fff;border:1px solid var(--line);color:var(--orange);display:grid;place-items:center}.hero .trust svg{width:19px;height:19px}
.hero .trust b{display:block;font-family:var(--head);color:var(--navy);font-size:.98rem}.hero .trust span{font-size:.84rem;color:var(--mut)}
.hero-media{position:relative;min-height:520px}
.hm-main{position:absolute;right:0;top:0;width:76%;height:88%;border-radius:220px 220px 26px 26px;overflow:hidden;background:var(--bg2);box-shadow:0 40px 70px -30px rgba(14,42,67,.4)}
.hm-sm{position:absolute;left:0;top:8%;width:38%;height:34%;border-radius:120px;overflow:hidden;background:var(--bg2);border:6px solid #fff;box-shadow:0 24px 44px -22px rgba(14,42,67,.4)}
.hm-sm2{position:absolute;left:3%;bottom:10%;width:34%;height:26%;border-radius:22px;overflow:hidden;background:var(--bg2);border:6px solid #fff;box-shadow:0 24px 44px -22px rgba(14,42,67,.4)}
.hm-card{position:absolute;right:-6px;bottom:16%;background:#fff;border-radius:16px;padding:16px 18px;box-shadow:0 26px 50px -22px rgba(14,42,67,.45);width:230px}
.hm-card .hc-t{font-family:var(--head);font-weight:600;color:var(--navy);font-size:.76rem;text-transform:uppercase;letter-spacing:1px;margin-bottom:10px;display:flex;align-items:center;gap:8px}
.hm-card .hc-t::before{content:"";width:9px;height:9px;border-radius:50%;background:var(--orange)}
.hm-card li{display:flex;align-items:center;gap:9px;font-size:.84rem;color:var(--navy);padding:4px 0;list-style:none}.hm-card ul{margin:0;padding:0}.hm-card li svg{width:15px;height:15px;color:var(--ok);flex:none}
.hm-stat{position:absolute;left:8%;bottom:-4%;background:var(--navy);color:#fff;border-radius:16px;padding:14px 18px;display:flex;align-items:center;gap:14px;box-shadow:0 26px 50px -22px rgba(0,0,0,.45)}
.hm-stat .hs-ic{width:40px;height:40px;border-radius:50%;background:var(--orange);color:#fff;display:grid;place-items:center}.hm-stat svg{width:20px;height:20px}
.hm-stat b{font-family:var(--head);font-size:1.4rem;display:block;line-height:1}.hm-stat span{font-size:.72rem;color:#9fb3c2}
.ebar{margin-top:-30px;position:relative;z-index:5}
.ebar .in{background:var(--navy);color:#fff;border-radius:18px;padding:22px 26px;display:flex;align-items:center;gap:20px;flex-wrap:wrap;box-shadow:0 30px 60px -34px rgba(14,42,67,.6)}
.ebar .eb-ic{width:52px;height:52px;border-radius:50%;background:var(--orange);color:#fff;display:grid;place-items:center;flex:none}.ebar .eb-ic svg{width:24px;height:24px}
.ebar .eb-tx{flex:1;min-width:240px}.ebar .eb-tx b{font-family:var(--head);font-size:1.15rem;color:#fff;display:flex;align-items:center;gap:9px}.ebar .eb-tx b::before{content:"";width:9px;height:9px;border-radius:50%;background:#49d17a}
.ebar .eb-tx p{margin:3px 0 0;color:#bcd0df;font-size:.94rem}
.ebar .eb-acts{display:flex;gap:12px;flex-wrap:wrap}
.help-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.help{display:flex;align-items:flex-start;gap:16px;background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;transition:.15s}
.help:hover{box-shadow:0 26px 50px -36px rgba(14,42,67,.5);transform:translateY(-3px)}
.help-ic{flex:none;width:54px;height:54px;border-radius:14px;background:var(--bg);color:var(--orange);display:grid;place-items:center}.help-ic svg{width:26px;height:26px}
.help h3{font-size:1.25rem;margin-bottom:5px}.help p{font-size:.92rem;margin:0}
.help-ar{margin-left:auto;color:var(--orange);align-self:center}.help-ar svg{width:20px;height:20px}
.finder-sec{background:#fff}
.finder{display:grid;grid-template-columns:1fr 1fr;gap:26px;align-items:start}
.f-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.ft{display:flex;align-items:center;gap:13px;text-align:left;background:var(--bg);border:2px solid transparent;border-radius:14px;padding:16px;cursor:pointer;font-family:var(--head);font-weight:600;font-size:1rem;color:var(--navy);transition:.15s}
.ft:hover{background:var(--bg2)}
.ft.on{background:#fff;border-color:var(--orange);box-shadow:0 10px 26px -16px rgba(242,106,33,.5)}
.ft-ic{flex:none;width:44px;height:44px;border-radius:11px;background:#fff;color:var(--orange);display:grid;place-items:center;box-shadow:0 4px 12px -6px rgba(14,42,67,.3)}.ft-ic svg{width:21px;height:21px}
.ft.on .ft-ic{background:var(--orange);color:#fff}
.f-stage{position:sticky;top:90px}
.fc{display:none;background:var(--navy);color:#fff;border-radius:20px;padding:34px}
.fc.on{display:block;animation:fade .25s ease}
@keyframes fade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.fc-tag{display:inline-flex;align-items:center;gap:7px;background:rgba(242,106,33,.16);color:var(--orange2);font-family:var(--head);font-weight:600;text-transform:uppercase;letter-spacing:1px;font-size:.72rem;padding:6px 13px;border-radius:999px}.fc-tag svg{width:14px;height:14px}
.fc h3{color:#fff;font-size:1.9rem;margin:16px 0 18px}
.fc p{color:#cdddea;font-size:.96rem;margin:0 0 16px}
.fc-k{display:block;font-family:var(--head);font-weight:600;color:var(--orange2);font-size:.72rem;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px}
.fc-now{background:rgba(255,255,255,.05);border-left:3px solid var(--orange);border-radius:0 10px 10px 0;padding:12px 15px;font-size:.9rem;color:#dce8f1;margin:4px 0 18px}.fc-now b{color:var(--orange2)}
.fc-meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:20px}
.fc-meta div{background:var(--navy2);border-radius:12px;padding:13px 15px}.fc-meta span{display:block;color:#9fb8cb;font-size:.72rem;text-transform:uppercase;letter-spacing:.5px}.fc-meta b{font-family:var(--head);font-size:1.25rem;color:#fff}
.fc-cta{display:flex;gap:12px;flex-wrap:wrap}
.fc-link{display:inline-block;margin-top:16px;color:var(--orange2);font-family:var(--head);font-weight:600;font-size:.92rem}
.svc-sec{background:var(--bg2)}
.svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.svc{display:flex;flex-direction:column;background:#fff;border-radius:20px;padding:24px;position:relative;transition:.15s}
.svc:hover{box-shadow:0 30px 56px -34px rgba(14,42,67,.5);transform:translateY(-4px)}
.svc-ic{position:absolute;right:22px;top:22px;width:46px;height:46px;border-radius:50%;background:var(--navy);color:#fff;display:grid;place-items:center}.svc-ic svg{width:22px;height:22px}
.svc h3{font-size:1.35rem;margin:4px 70px 8px 0}.svc p{font-size:.92rem;margin:0 0 18px;flex:1}
.svc-img{height:180px;border-radius:14px;overflow:hidden;background:var(--bg)}
.proc{background:var(--bg)}
.proc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:10px}
.step{display:flex;flex-direction:column;align-items:center;text-align:center}
.step.s1{margin-top:60px}
.step-img{position:relative;width:200px;height:200px}
.step-ph{width:100%;height:100%;border-radius:50%;overflow:hidden;background:var(--bg2);box-shadow:0 26px 50px -30px rgba(14,42,67,.5)}
.step-n{position:absolute;left:50%;bottom:-18px;transform:translateX(-50%);width:44px;height:44px;border-radius:50%;background:var(--orange);color:#fff;font-family:var(--head);font-weight:700;font-size:.95rem;display:grid;place-items:center;border:4px solid var(--bg);box-shadow:0 8px 18px -8px rgba(242,106,33,.7);z-index:3}
.step-tx{margin-top:28px}.step-tx h3{font-size:1.3rem;margin-bottom:7px}.step-tx p{font-size:.9rem;margin:0}
.price-sec{background:#fff}
.price-grid{display:grid;grid-template-columns:1fr 1fr;gap:46px;align-items:start}
.price-l h2{font-size:clamp(1.9rem,3.6vw,2.7rem);margin:10px 0 14px}
.fac{display:flex;gap:15px;background:var(--bg);border:1px solid var(--line);border-radius:14px;padding:16px 18px;margin-bottom:12px}
.fac-high{border-color:rgba(242,106,33,.35)}
.fac-ic{flex:none;width:44px;height:44px;border-radius:11px;background:#fff;color:var(--orange);display:grid;place-items:center}.fac-ic svg{width:21px;height:21px}
.fac-top{display:flex;justify-content:space-between;align-items:center;gap:10px}.fac-top b{font-family:var(--head);color:var(--navy);font-size:1.05rem}
.fac p{margin:3px 0 0;font-size:.88rem}
.imp{font-family:var(--head);font-weight:600;font-size:.7rem;text-transform:uppercase;letter-spacing:.5px;padding:3px 9px;border-radius:999px;white-space:nowrap}
.imp-high{background:rgba(242,106,33,.14);color:var(--orange)}.imp-medium{background:#eaf0f6;color:#5b7186}.imp-low{background:#eef2f6;color:#8295a4}
.price-card{background:var(--navy);color:#fff;border-radius:22px;overflow:hidden;position:sticky;top:90px}
.pc-head{background:var(--navy2);padding:22px 26px;display:flex;align-items:center;gap:14px}
.pc-head .pc-ic{width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.1);color:var(--orange2);display:grid;place-items:center}.pc-head svg{width:22px;height:22px}
.pc-head b{font-family:var(--head);font-size:1.15rem}.pc-head span{display:block;color:#9fb8cb;font-size:.82rem}
.pc-body{padding:26px}
.pc-amt{font-family:var(--head);font-size:2.6rem;font-weight:700;color:#fff;line-height:1}.pc-amt small{font-size:.9rem;color:var(--orange2);font-weight:600}
.pc-sub{color:#9fb8cb;font-size:.86rem;margin:2px 0 18px}
.pc-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:11px}
.pc-list li{display:flex;align-items:center;gap:10px;color:#dce8f1;font-size:.94rem}.pc-list svg{width:16px;height:16px;color:var(--orange2);flex:none}
.pc-note{color:#7f96a9;font-size:.8rem;margin-top:18px;border-top:1px solid rgba(255,255,255,.1);padding-top:16px}
.area-sec{background:var(--navy);color:#fff;position:relative;overflow:hidden}
.area-grid{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.area-l h2{color:#fff;font-size:clamp(1.9rem,3.6vw,2.7rem);margin:12px 0 14px}.area-l p{color:#bcd0df}
.area-l .k{color:var(--orange2)}
.zip{display:flex;gap:10px;background:#fff;border-radius:999px;padding:7px 7px 7px 18px;margin-top:20px;max-width:430px}
.zip input{flex:1;border:none;outline:none;font-family:var(--sans);font-size:1rem;color:var(--navy);background:transparent}
.radar{position:relative;aspect-ratio:1/.8;border-radius:20px;background:radial-gradient(circle at 60% 45%,#143147,var(--navy2));overflow:hidden;border:1px solid rgba(255,255,255,.08)}
.radar svg.rings{position:absolute;inset:0;width:100%;height:100%}
.area-chips{position:absolute;left:24px;bottom:22px;right:24px;display:flex;flex-wrap:wrap;gap:8px}
.area-chips .ac-k{width:100%;color:var(--orange2);font-family:var(--head);font-weight:600;font-size:.74rem;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px}
.area-chips .lga{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);color:#dce8f1;font-size:.82rem;border-radius:999px;padding:6px 13px}
.rev-sec{background:var(--bg)}
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:46px}
.rev{background:#fff;border-radius:18px;padding:52px 26px 26px;position:relative;text-align:center;margin-top:30px}
.rev.hot{background:var(--navy);color:#fff;transform:translateY(-16px)}
.rev-av{position:absolute;left:50%;top:-30px;transform:translateX(-50%);width:64px;height:64px;border-radius:50%;overflow:hidden;border:4px solid #fff;background:var(--bg2)}
.rev.hot .rev-av{border-color:var(--navy)}
.rev-stars{color:var(--orange);display:flex;gap:3px;justify-content:center;margin-bottom:12px}.rev-stars svg{width:16px;height:16px}
.rev p{font-size:.94rem;margin:0 0 16px}.rev.hot p{color:#dce8f1}
.rev-by b{font-family:var(--head);color:var(--navy);display:block}.rev.hot .rev-by b{color:#fff}.rev-by span{font-size:.84rem;color:var(--mut)}
.book-sec{background:var(--navy);color:#fff}
.book-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:40px;align-items:start}
.book-l .k{color:var(--orange2)}.book-l h2{color:#fff;font-size:clamp(1.9rem,3.6vw,2.7rem);margin:12px 0 14px}.book-l p{color:#bcd0df}
.book-img{border-radius:18px;overflow:hidden;height:240px;background:var(--navy2);margin:22px 0}
.book-pts{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px}
.book-pts li{display:flex;align-items:center;gap:12px;color:#dce8f1}.book-pts .bp-ic{width:38px;height:38px;border-radius:10px;background:rgba(255,255,255,.08);color:var(--orange2);display:grid;place-items:center}.book-pts svg{width:18px;height:18px}
.book-card{background:#fff;border-radius:20px;padding:30px}
.book-card h3{font-size:.8rem;text-transform:uppercase;letter-spacing:1px;color:var(--mut);margin-bottom:14px}
.brow{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.bfield{margin-bottom:14px}.bfield label{display:block;font-size:.78rem;font-weight:600;color:var(--navy);margin-bottom:6px;font-family:var(--head)}.bfield .rq{color:var(--orange)}
.bfield input,.bfield select,.bfield textarea{width:100%;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:12px 13px;font-family:var(--sans);font-size:.94rem;color:var(--navy)}
.bfield textarea{min-height:90px;resize:vertical}
.bphotos{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin:6px 0 16px}
.bphoto{border:1px dashed #c7d2dc;border-radius:12px;padding:16px 10px;text-align:center;cursor:pointer}
.bphoto .bp-c{width:38px;height:38px;border-radius:10px;background:rgba(242,106,33,.12);color:var(--orange);display:grid;place-items:center;margin:0 auto 8px}.bphoto svg{width:19px;height:19px}
.bphoto b{display:block;font-family:var(--head);color:var(--navy);font-size:.82rem}.bphoto span{font-size:.72rem;color:var(--mut)}
.faq-sec{background:#fff}
.faq-wrap{max-width:860px;margin:0 auto}
.fq{border:1px solid var(--line);border-radius:13px;margin:12px 0;overflow:hidden;background:#fff}
.fq summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:14px;padding:18px 22px;font-family:var(--head);font-weight:600;color:var(--navy);font-size:1.08rem}
.fq summary::-webkit-details-marker{display:none}
.fq .cv{color:var(--orange);transition:.2s}.fq .cv svg{width:18px;height:18px;transform:rotate(90deg)}.fq[open] .cv svg{transform:rotate(-90deg)}
.fa{padding:0 22px 20px;color:var(--body)}
footer.site{background:var(--navy2);color:#9fb2c2;font-size:.92rem;position:relative;overflow:hidden}
.fcta{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08);border-radius:18px;padding:22px 26px;display:flex;align-items:center;gap:20px;flex-wrap:wrap;margin:52px 0 44px}
.fcta .fc-ic{width:52px;height:52px;border-radius:50%;background:var(--orange);color:#fff;display:grid;place-items:center;flex:none}.fcta svg{width:24px;height:24px}
.fcta .fc-tx{flex:1;min-width:240px}.fcta b{font-family:var(--head);color:#fff;font-size:1.15rem}.fcta p{margin:3px 0 0;color:#bcd0df;font-size:.92rem}
.fcta .fc-acts{display:flex;gap:12px;flex-wrap:wrap}
.fgrid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1.2fr;gap:34px;padding-bottom:30px;position:relative;z-index:2}
footer .logo{height:38px;margin-bottom:16px}
footer h4{color:#fff;font-family:var(--head);font-size:.82rem;text-transform:uppercase;letter-spacing:1.5px;margin:0 0 14px}
footer a{display:block;color:#9fb2c2;padding:5px 0}footer a:hover{color:var(--orange2)}
.f-tick{display:flex;align-items:center;gap:9px;color:#cdd9e3;padding:4px 0}.f-tick svg{width:16px;height:16px;color:var(--orange2)}
.f-cont a{display:flex;gap:10px;align-items:center}.f-cont svg{width:16px;height:16px;color:var(--orange2);flex:none}
.f-socials{display:flex;gap:10px;margin-top:16px}.f-socials a{width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.08);display:grid;place-items:center;padding:0}.f-socials svg{width:17px;height:17px}
.f-wm{position:absolute;left:0;right:0;bottom:46px;text-align:center;font-family:var(--head);font-weight:800;font-size:clamp(3rem,13vw,10rem);color:rgba(255,255,255,.03);letter-spacing:-3px;z-index:1;pointer-events:none;white-space:nowrap}
.fbar{border-top:1px solid rgba(255,255,255,.1);padding:16px 22px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:.84rem;position:relative;z-index:2}
.enq-toggle{position:fixed;top:0;left:0;opacity:0;pointer-events:none}
.enq-tab{position:fixed;right:0;top:31%;z-index:55;background:var(--orange);color:#fff;border-radius:16px 0 0 16px;cursor:pointer;box-shadow:-8px 0 24px -10px rgba(0,0,0,.45);display:flex;flex-direction:column;align-items:center;gap:11px;padding:11px 11px 17px;transition:.2s}
.enq-tab:hover{background:var(--orange2);padding-right:15px}
.enq-tab-ic{width:36px;height:36px;border-radius:50%;background:#fff;display:grid;place-items:center;box-shadow:0 5px 12px -4px rgba(0,0,0,.45)}
.enq-tab-ic svg{width:32px;height:32px;display:block}
.enq-tab-tx{writing-mode:vertical-rl;font-family:var(--head);font-weight:700;text-transform:uppercase;letter-spacing:2.5px;font-size:.8rem;display:flex;align-items:center;gap:12px}
.enq-tab-tx svg{width:15px;height:15px;transform:rotate(90deg)}
.enq-veil{position:fixed;inset:0;background:rgba(10,32,51,.55);opacity:0;visibility:hidden;transition:.25s;z-index:90;cursor:pointer}
.enq-panel{position:fixed;top:0;right:0;height:100%;width:min(470px,100%);background:var(--navy);color:#fff;transform:translateX(102%);transition:transform .32s cubic-bezier(.4,0,.2,1);z-index:95;overflow-y:auto;padding:30px 30px 44px}
.enq-toggle:checked ~ .enq-veil{opacity:1;visibility:visible}
.enq-toggle:checked ~ .enq-panel{transform:none}
.enq-toggle:checked ~ .enq-tab{opacity:0;pointer-events:none}
.enq-x{position:absolute;right:20px;top:20px;width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.1);color:#fff;display:grid;place-items:center;cursor:pointer;font-size:1.3rem}
.enq-art{height:150px;background:radial-gradient(circle at 46% 42%,#12314a,var(--navy2));border:1px solid rgba(255,255,255,.08);border-radius:14px;margin:6px 0 18px;display:grid;place-items:center;overflow:hidden}.enq-art svg{width:230px;height:140px}
.enq-h{display:inline-block;background:rgba(242,106,33,.16);color:var(--orange2);font-family:var(--head);font-weight:600;text-transform:uppercase;letter-spacing:1.5px;font-size:.7rem;padding:5px 12px;border-radius:999px}
.enq-panel h3{color:#fff;font-size:1.7rem;margin:14px 0 6px}.enq-panel .esub{color:#bcd0df;font-size:.92rem;margin:0 0 20px}
.efield{margin-bottom:14px}.efield label{display:block;font-size:.72rem;font-weight:600;text-transform:uppercase;letter-spacing:1px;color:#9fb8cb;margin-bottom:6px;font-family:var(--head)}.efield .req{color:var(--orange2)}
.efield input,.efield select,.efield textarea{width:100%;background:var(--navy2);border:1px solid rgba(255,255,255,.14);border-radius:10px;padding:12px 13px;color:#fff;font-family:var(--sans);font-size:.95rem}.efield textarea{min-height:90px;resize:vertical}
.erow{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.esub-btn{width:100%;justify-content:center;margin-top:6px}
.eval{background:rgba(242,106,33,.1);border:1px solid rgba(242,106,33,.3);border-radius:14px;padding:16px 18px;margin-top:20px}
.eval-top{display:flex;align-items:baseline;gap:10px;margin-bottom:12px;flex-wrap:wrap}.eval-amt{font-family:var(--head);font-weight:700;color:#fff;font-size:1.95rem;line-height:1;white-space:nowrap}.eval-amt small{font-size:.62rem;color:var(--orange2);text-transform:uppercase;letter-spacing:1px;margin-left:5px;font-weight:600}.eval-lb{color:#cdddea;font-size:.9rem;font-weight:600}
.eval ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}.eval li{display:flex;align-items:center;gap:9px;color:#dce8f1;font-size:.88rem}.eval li svg{width:15px;height:15px;color:var(--orange2);flex:none}
.ecall{display:flex;align-items:center;gap:13px;margin-top:20px;padding-top:18px;border-top:1px solid rgba(255,255,255,.12)}.ecall .ec-ic{width:42px;height:42px;border-radius:50%;background:var(--orange);color:#fff;display:grid;place-items:center}.ecall svg{width:20px;height:20px}.ecall small{display:block;color:#9fb8cb;font-size:.72rem;text-transform:uppercase;letter-spacing:1px}.ecall b{font-size:1.3rem;color:#fff;font-family:var(--head)}
.enq-foot{display:flex;flex-direction:column;align-items:center;gap:10px;margin-top:22px;padding-top:18px;border-top:1px solid rgba(255,255,255,.12)}.enq-foot img{height:30px;width:auto}.enq-foot .efine{margin:0;text-align:center;color:#7f96a9;font-size:.78rem}
/* interior page hero */
.ph{background:var(--navy);color:#fff;position:relative;overflow:hidden;padding:60px 0 58px}
.ph::after{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.045) 1.3px,transparent 1.3px);background-size:24px 24px;pointer-events:none}
.ph .wrap{position:relative;z-index:2;max-width:880px}
.ph .crumb{color:#9fb8cb;font-size:.84rem;margin-bottom:16px}.ph .crumb a:hover{color:#fff}.ph .crumb b{color:var(--orange2);font-weight:500}
.ph .eyebrow{background:rgba(242,106,33,.16);border-color:transparent;color:var(--orange2);box-shadow:none}
.ph h1{color:#fff;font-size:clamp(2.2rem,4.8vw,3.5rem);margin:14px 0 14px}
.ph p{color:#bcd0df;font-size:1.14rem;max-width:62ch}
.ph .ph-acts{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}
/* generic two-col + content blocks */
.two{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center}
.two.top{align-items:start}
.lead{font-size:1.16rem;color:var(--body)}
.media-card{border-radius:20px;overflow:hidden;height:440px;background:var(--bg2);box-shadow:0 30px 60px -34px rgba(14,42,67,.5)}
.media-card.sm{height:340px}
.wgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.wgrid.four{grid-template-columns:repeat(4,1fr)}
.wcard{background:#fff;border:1px solid var(--line);border-radius:18px;padding:26px}
.wcard .wic{width:52px;height:52px;border-radius:13px;background:var(--bg);color:var(--orange);display:grid;place-items:center;margin-bottom:14px}.wcard .wic svg{width:25px;height:25px}
.wcard h3{font-size:1.18rem;margin-bottom:7px}.wcard p{font-size:.93rem;margin:0}
.wcard .wn{font-family:var(--head);font-weight:800;color:var(--orange);font-size:1.3rem;display:block;margin-bottom:8px}
.excl{display:flex;gap:16px;background:var(--bg);border:1px solid var(--line);border-left:4px solid var(--orange);border-radius:0 14px 14px 0;padding:22px 24px;margin-top:24px}
.excl .ex-ic{flex:none;width:46px;height:46px;border-radius:12px;background:#fff;color:var(--orange);display:grid;place-items:center}.excl .ex-ic svg{width:22px;height:22px}
.excl h4{font-size:1.05rem;margin-bottom:5px}.excl p{margin:0;font-size:.93rem}
.chk{list-style:none;margin:18px 0 0;padding:0;display:flex;flex-direction:column;gap:11px}
.chk li{display:flex;gap:11px;align-items:flex-start;color:var(--body)}.chk li svg{width:20px;height:20px;color:var(--orange);flex:none;margin-top:2px}
.chk li b{color:var(--navy);font-family:var(--head)}
.stat-row{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:40px}
.stat{background:#fff;border:1px solid var(--line);border-radius:16px;padding:24px;text-align:center}
.stat b{font-family:var(--head);font-weight:800;color:var(--orange);font-size:2.1rem;display:block}.stat span{font-size:.92rem}
.ctaband{background:var(--navy);color:#fff;border-radius:22px;padding:40px;text-align:center;position:relative;overflow:hidden}
.ctaband h2{color:#fff;font-size:clamp(1.7rem,3.4vw,2.4rem);margin-bottom:10px}.ctaband p{color:#bcd0df;max-width:52ch;margin:0 auto 22px}
.ctaband .cta-acts{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
/* contact */
.ct-grid{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start}
.ct-cards{display:flex;flex-direction:column;gap:14px}
.ct-card{display:flex;gap:16px;background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px}
.ct-card .ct-ic{flex:none;width:50px;height:50px;border-radius:13px;background:var(--bg);color:var(--orange);display:grid;place-items:center}.ct-card svg{width:24px;height:24px}
.ct-card h3{font-size:1.08rem;margin-bottom:3px}.ct-card p{margin:0;font-size:.94rem}.ct-card a{color:var(--navy);font-weight:600}
.ct-map{height:280px;border-radius:16px;overflow:hidden;background:var(--bg2);margin-top:4px}
.hours{list-style:none;margin:6px 0 0;padding:0}
.hours li{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-bottom:1px solid var(--line);font-size:.94rem}.hours li:last-child{border-bottom:none}.hours b{color:var(--navy);font-family:var(--head)}
/* thank-you */
.ty{text-align:center;max-width:720px;margin:0 auto}
.ty-ic{width:92px;height:92px;border-radius:50%;background:rgba(242,106,33,.12);color:var(--orange);display:grid;place-items:center;margin:0 auto 22px}.ty-ic svg{width:46px;height:46px}
.ty h1{font-size:clamp(2.2rem,4.8vw,3.2rem);margin-bottom:14px}
.ty>.lead{margin:0 auto 10px;max-width:56ch}
.ty-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:36px 0;text-align:left}
.ty-acts{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:10px}
/* mobile menu */
.mnav-toggle{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.burger{width:46px;height:46px;border-radius:11px;border:1px solid var(--line);background:#fff;display:none;place-items:center;cursor:pointer;flex:none;margin-left:4px}
.burger span{position:relative;display:block;width:21px;height:2px;background:var(--navy);border-radius:2px;transition:.22s}
.burger span::before,.burger span::after{content:"";position:absolute;left:0;width:21px;height:2px;background:var(--navy);border-radius:2px;transition:.22s}
.burger span::before{top:-6px}.burger span::after{top:6px}
.mnav-toggle:checked~.hd .burger span{background:transparent}
.mnav-toggle:checked~.hd .burger span::before{top:0;transform:rotate(45deg)}
.mnav-toggle:checked~.hd .burger span::after{top:0;transform:rotate(-45deg)}
.mnav{display:none}
.mnav a{display:block;padding:13px 22px;font-family:var(--head);font-weight:600;color:var(--navy);border-bottom:1px solid var(--line)}
.mnav a.sub{padding-left:40px;font-weight:500;font-size:.92rem;color:var(--body)}
.mnav a:hover{color:var(--orange)}
.mnav-cta{padding:16px 22px 20px;display:flex;flex-direction:column;gap:10px}
.mnav-cta .btn{justify-content:center;width:100%}
